import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { api } from '../utils/api';

const CATEGORIES = [
  { value: 'all', label: 'All Categories' },
  { value: 'restaurant', label: '🍽️ Restaurant' },
  { value: 'clinic', label: '🏥 Clinic' },
  { value: 'salon', label: '💇 Salon' },
  { value: 'bank', label: '🏦 Bank' },
  { value: 'government', label: '🏛️ Government' },
  { value: 'retail', label: '🛍️ Retail' },
  { value: 'education', label: '📚 Education' },
  { value: 'fitness', label: '💪 Fitness' },
  { value: 'other', label: '📦 Other' },
];

export default function BusinessListing() {
  const navigate = useNavigate();
  const [businesses, setBusinesses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');

  const fetchBusinesses = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (searchQuery) params.append('search', searchQuery);
      if (selectedCategory !== 'all') params.append('category', selectedCategory);

      const res = await api.get(`/business/all?${params.toString()}`);
      setBusinesses(res.data || []);
    } catch (err) {
      console.error('Failed to fetch businesses:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchBusinesses();
  }, [searchQuery, selectedCategory]);

  const handleSearch = (e) => {
    setSearchQuery(e.target.value);
  };

  const getCategoryLabel = (category) => {
    const cat = CATEGORIES.find(c => c.value === category);
    return cat ? cat.label : category;
  };

  return (
    <div style={{ minHeight: '100vh', background: '#F8FAFC' }}>
      {/* Header */}
      <div style={{ background: 'linear-gradient(135deg, #0F172A 0%, #1E293B 100%)', color: 'white', padding: '48px 24px' }}>
        <div style={{ maxWidth: 1200, margin: '0 auto' }}>
          <h1 style={{ fontSize: 32, fontWeight: 800, marginBottom: 8 }}>Find Businesses</h1>
          <p style={{ fontSize: 16, opacity: 0.8 }}>Browse and book queue tokens at registered businesses</p>
        </div>
      </div>

      <div style={{ maxWidth: 1200, margin: '-32px auto 0', padding: '0 24px 48px', position: 'relative', zIndex: 1 }}>
        {/* Search and Filter Bar */}
        <div style={{ background: 'white', borderRadius: 20, padding: 24, border: '1px solid #E2E8F0', boxShadow: '0 4px 20px rgba(0,0,0,0.06)', marginBottom: 24 }}>
          <div style={{ display: 'flex', gap: 16, flexWrap: 'wrap' }}>
            <div style={{ flex: 1, minWidth: 280 }}>
              <input
                type="text"
                placeholder="🔍 Search by name, city, or category..."
                value={searchQuery}
                onChange={handleSearch}
                style={{
                  width: '100%',
                  padding: '14px 18px',
                  border: '1.5px solid #E2E8F0',
                  borderRadius: 12,
                  fontSize: 15,
                  fontFamily: 'inherit',
                  outline: 'none',
                  background: '#F8FAFC',
                  transition: 'border-color 0.2s',
                }}
              />
            </div>
            <div style={{ minWidth: 200 }}>
              <select
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
                style={{
                  width: '100%',
                  padding: '14px 18px',
                  border: '1.5px solid #E2E8F0',
                  borderRadius: 12,
                  fontSize: 15,
                  fontFamily: 'inherit',
                  outline: 'none',
                  background: '#F8FAFC',
                  cursor: 'pointer',
                }}
              >
                {CATEGORIES.map(cat => (
                  <option key={cat.value} value={cat.value}>{cat.label}</option>
                ))}
              </select>
            </div>
          </div>
        </div>

        {/* Results Count */}
        {!loading && (
          <div style={{ marginBottom: 16, color: '#64748B', fontSize: 14 }}>
            {businesses.length} {businesses.length === 1 ? 'business' : 'businesses'} found
          </div>
        )}

        {/* Business Grid */}
        {loading ? (
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '40vh' }}>
            <div style={{ textAlign: 'center' }}>
              <div style={{ fontSize: 40, marginBottom: 16, animation: 'spin 2s linear infinite' }}>⏳</div>
              <div style={{ color: '#64748B', fontSize: 15 }}>Loading businesses...</div>
            </div>
          </div>
        ) : businesses.length === 0 ? (
          <div style={{ background: 'white', borderRadius: 20, padding: '48px 24px', textAlign: 'center', border: '1px solid #E2E8F0' }}>
            <div style={{ fontSize: 48, marginBottom: 16 }}>🔍</div>
            <h2 style={{ fontSize: 22, fontWeight: 700, color: '#0F172A', marginBottom: 8 }}>No businesses found</h2>
            <p style={{ color: '#64748B', fontSize: 15, marginBottom: 24 }}>
              Try adjusting your search or filter criteria
            </p>
            <button
              onClick={() => { setSearchQuery(''); setSelectedCategory('all'); }}
              style={{
                background: '#3B82F6',
                color: 'white',
                border: 'none',
                borderRadius: 12,
                padding: '12px 24px',
                fontSize: 14,
                fontWeight: 600,
                cursor: 'pointer',
              }}
            >
              Clear Filters
            </button>
          </div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(350px, 1fr))', gap: 20 }}>
            {businesses.map(business => (
              <div
                key={business._id}
                onClick={() => navigate(`/q/${business.slug}`)}
                style={{
                  background: 'white',
                  borderRadius: 20,
                  padding: 24,
                  border: '1px solid #E2E8F0',
                  cursor: 'pointer',
                  transition: 'all 0.2s',
                  boxShadow: '0 2px 12px rgba(0,0,0,0.04)',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = 'translateY(-4px)';
                  e.currentTarget.style.boxShadow = '0 8px 30px rgba(0,0,0,0.08)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = 'translateY(0)';
                  e.currentTarget.style.boxShadow = '0 2px 12px rgba(0,0,0,0.04)';
                }}
              >
                <div style={{ display: 'flex', alignItems: 'flex-start', gap: 16, marginBottom: 16 }}>
                  {business.logo ? (
                    <img
                      src={business.logo}
                      alt=""
                      style={{ width: 56, height: 56, borderRadius: 14, objectFit: 'cover' }}
                    />
                  ) : (
                    <div style={{
                      width: 56,
                      height: 56,
                      borderRadius: 14,
                      background: `linear-gradient(135deg, ${business.primaryColor || '#0F172A'}, ${business.accentColor || '#10B981'})`,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontSize: 24,
                      color: 'white',
                      fontWeight: 700,
                    }}>
                      {business.name?.charAt(0) || 'B'}
                    </div>
                  )}
                  <div style={{ flex: 1 }}>
                    <h3 style={{ fontSize: 17, fontWeight: 700, color: '#0F172A', marginBottom: 4 }}>
                      {business.name}
                    </h3>
                    {business.tagline && (
                      <p style={{ fontSize: 13, color: '#64748B', lineHeight: 1.4 }}>
                        {business.tagline}
                      </p>
                    )}
                  </div>
                </div>

                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 16 }}>
                  <span style={{
                    padding: '4px 12px',
                    borderRadius: 999,
                    fontSize: 11,
                    fontWeight: 600,
                    background: '#EFF6FF',
                    color: '#2563EB',
                  }}>
                    {getCategoryLabel(business.category)}
                  </span>
                  {business.city && (
                    <span style={{
                      padding: '4px 12px',
                      borderRadius: 999,
                      fontSize: 11,
                      fontWeight: 600,
                      background: '#F1F5F9',
                      color: '#64748B',
                    }}>
                      📍 {business.city}
                    </span>
                  )}
                </div>

                {business.description && (
                  <p style={{
                    fontSize: 13,
                    color: '#64748B',
                    lineHeight: 1.5,
                    marginBottom: 16,
                    display: '-webkit-box',
                    WebkitLineClamp: 2,
                    WebkitBoxOrient: 'vertical',
                    overflow: 'hidden',
                  }}>
                    {business.description}
                  </p>
                )}

                <div style={{ display: 'flex', gap: 12, fontSize: 12, color: '#94A3B8' }}>
                  {business.phone && <span>📞 {business.phone}</span>}
                  {business.address && <span>📍 {business.address}</span>}
                </div>

                <button
                  style={{
                    width: '100%',
                    marginTop: 16,
                    padding: '12px',
                    background: `linear-gradient(135deg, ${business.primaryColor || '#0F172A'}, ${business.accentColor || '#10B981'})`,
                    color: 'white',
                    border: 'none',
                    borderRadius: 12,
                    fontSize: 14,
                    fontWeight: 600,
                    cursor: 'pointer',
                    transition: 'all 0.2s',
                  }}
                >
                  Book Queue →
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
